import{_ as a,c as o,o as t,ae as s}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"UI Framework 策略","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ui-framework.md","filePath":"guide/ui-framework.md","lastUpdated":1792605191000}'),r={name:"guide/ui-framework.md"};function i(n,e,c,d,p,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="ui-framework-策略" tabindex="-1">UI Framework 策略 <a class="header-anchor" href="#ui-framework-策略" aria-label="Permalink to &quot;UI Framework 策略&quot;">​</a></h1><p>模板保留 Vant、NutUI 和 Varlet 的选择能力，但 production build 必须单选：</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VITE_UI_FRAMEWORK=vant</span></span></code></pre></div><p>Vite 根据该值选择 resolver、SCSS 注入和 <code>#ui-demo</code> alias。因此业务代码无需散落条件判断，另外两套框架不会进入当前构建图。</p><p>核心 Layout、AI Chat 与工程示例使用模板自己的轻量样式和 <code>SvgIcon</code>，避免跨框架耦合。真实项目应在初始化时选择一个 UI 框架，未来 CLI 会删除未选依赖。</p><h2 id="svg-icon" tabindex="-1">SVG Icon <a class="header-anchor" href="#svg-icon" aria-label="Permalink to &quot;SVG Icon&quot;">​</a></h2><p>产品图标放在 <code>src/assets/icons/*.svg</code>，插件自动生成 sprite，统一通过类型化 <code>&lt;SvgIcon name=&quot;ai&quot; /&gt;</code> 使用。UI 框架自带 icon 只在框架局部使用，不加入产品 icon union。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>全局 Design Tokens 位于 <code>src/styles/index.scss</code>，组件复杂布局继续使用 scoped SCSS。项目没有引入 UnoCSS：当前结构不需要第二套原子样式范式。viewport 插件按 750 设计稿转换业务 px，并为 UI 库使用 375 宽度；新增交互需检查转换后的 44 CSS px 触摸目标、safe-area、dark scheme 和 focus-visible。</p>',9)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
